import re

from moler.exceptions import ParsingDone
from moler.cmd.unix.genericunix import GenericUnixCommand

__author__ = 'Dariusz Rosinski'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'dariusz.rosinski@nokia.com'


class Mmi(GenericUnixCommand):
    """Command for execute sector/tgr connect procedure."""

    def __init__(self, connection, dsp_number, expected_prompt=None, prompt=None, newline_chars=None, runner=None):
        """
        Mmi command for stat transitoin to dsp.

        :param connection: moler connection to device, terminal when command is executed.
        :param dsp_number: number of dsp to connect (1-8).
        :param expected_prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Mmi, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.dsp_number = dsp_number
        self.expected_prompt = self._calculate_prompt(expected_prompt)
        self.current_ret = {}
        self.ret_required = True

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return f"mmi {self.dsp_number}"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._send_enter_at_command_end(line)
                self._search_for_expected_prompt(line)
            except ParsingDone:
                pass
        return super(Mmi, self).on_new_line(line, is_full_line)

    def _search_for_expected_prompt(self, line):
        if re.match(self.expected_prompt, line):
            self.set_result({})
            raise ParsingDone

    def _send_enter_at_command_end(self, line):
        if re.match(r'\[i\] Tx read pos', line):
            self.connection.sendline('\n')
            raise ParsingDone


